# Completa la línea marcada y compruébala con py check.
def sin_evidencia(soa):
    # soa: lista de {"id": ..., "aplica": True/False, "evidencias": [...]}
    salida = []
    for o in soa:
        if o["aplica"]:   # ← cambia esta línea: además, que la lista de evidencias esté vacía
            salida.append(o["id"])
    return salida

print(sin_evidencia([{"id": "A.2", "aplica": True, "evidencias": ["Política v1.2"]}, {"id": "A.5", "aplica": True, "evidencias": []}]))   # ['A.5']
